MONTHS = {'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
          'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12}
PRESENT = {'present', 'current', 'now'}

def normalize(s, side, ref, mode='generous'):
    """Return (year, month); side is 'start' or 'end'."""
    s = s.strip()
    if s.lower() in PRESENT:
        return (ref.year, ref.month)          # anchored to the reference date
    parts = s.split()
    if len(parts) == 2:                       # 'Sep 2018': month precision
        return (int(parts[1]), MONTHS[parts[0]])
    year = int(s)                             # '2021': year precision
    if mode == 'generous':
        return (year, 1) if side == 'start' else (year, 12)
    # strict; the caller then clamps end up to start ('2017 to 2017' is 2017-12)
    return (year, 12) if side == 'start' else (year, 1)

def merge(roles):
    # roles: list of (start, end) month indices, end exclusive
    roles = sorted(roles)
    merged = []
    gaps = []
    for s, e in roles:
        if merged and s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            if merged:
                gaps.append((merged[-1][1], s))
            merged.append([s, e])
    return merged, gaps

merged, gaps = merge(roles)
total = sum(e - s for s, e in merged)
